CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY,name TEXT NOT NULL,email TEXT UNIQUE NOT NULL,password TEXT NOT NULL,role TEXT NOT NULL DEFAULT 'user');
CREATE TABLE IF NOT EXISTS vehicles(id INTEGER PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id),plate TEXT UNIQUE NOT NULL);
CREATE TABLE IF NOT EXISTS spaces(id INTEGER PRIMARY KEY,label TEXT UNIQUE NOT NULL,rate INTEGER NOT NULL CHECK(rate > 0),area TEXT NOT NULL DEFAULT 'General',status TEXT NOT NULL DEFAULT 'available' CHECK(status IN ('available','occupied','maintenance')));
CREATE TABLE IF NOT EXISTS bookings(id INTEGER PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id),vehicle_id INTEGER NOT NULL REFERENCES vehicles(id),space_id INTEGER NOT NULL REFERENCES spaces(id),hours INTEGER CHECK(hours BETWEEN 1 AND 24),amount INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','cancelled','completed')),booking_type TEXT NOT NULL DEFAULT 'normal' CHECK(booking_type IN ('normal','emergency')),created TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX IF NOT EXISTS active_space ON bookings(space_id) WHERE status='active';
CREATE UNIQUE INDEX IF NOT EXISTS active_vehicle ON bookings(vehicle_id) WHERE status='active';
CREATE TABLE IF NOT EXISTS payments(id INTEGER PRIMARY KEY,booking_id INTEGER NOT NULL UNIQUE REFERENCES bookings(id),user_id INTEGER NOT NULL REFERENCES users(id),amount INTEGER NOT NULL,payment_status TEXT NOT NULL DEFAULT 'pending' CHECK(payment_status IN ('pending','paid')),payment_method TEXT NOT NULL DEFAULT 'demo',created TEXT DEFAULT CURRENT_TIMESTAMP,paid_at TEXT);
CREATE TRIGGER IF NOT EXISTS booking_occupies_space AFTER INSERT ON bookings WHEN NEW.status='active' BEGIN UPDATE spaces SET status='occupied' WHERE id=NEW.space_id AND status!='maintenance'; END;
CREATE TRIGGER IF NOT EXISTS booking_releases_space AFTER UPDATE OF status ON bookings WHEN OLD.status='active' AND NEW.status!='active' BEGIN UPDATE spaces SET status='available' WHERE id=OLD.space_id AND status='occupied' AND NOT EXISTS(SELECT 1 FROM bookings WHERE space_id=OLD.space_id AND status='active'); END;
CREATE TRIGGER IF NOT EXISTS booking_delete_releases_space AFTER DELETE ON bookings BEGIN UPDATE spaces SET status='available' WHERE id=OLD.space_id AND status='occupied' AND NOT EXISTS(SELECT 1 FROM bookings WHERE space_id=OLD.space_id AND status='active'); END;
